var FnGeo={arrTargets:[],init:function(successFn){var arrTargets=FnGeo.arrTargets;if(0==arrTargets.length)return Log.write("arrTargets.length為0","FnGeo"),void(successFn&&successFn());for(var lastItem=arrTargets.length-1,i=0;i<arrTargets.length;i++){var targetId,selector="#"+arrTargets[i];$(selector).twzipcode(),$(selector).twzipcode("reset"),i===lastItem&&successFn&&successFn()}},getZipcode:function(targetId){var selector,zipcode=$("#"+targetId).twzipcode("get","zipcode");return Log.write(zipcode,"FnGeo getZipcode"),zipcode+""},setZipcode:function(targetId,zipcode){var selector="#"+targetId;Log.write(selector,"FnGeo setZipcode"),Log.write(zipcode,"FnGeo setZipcode"),$(selector).twzipcode("set",+zipcode)}};